 pj * (x*x - xl*xl) + qj * (x - xl);\n        return val;\n    };\n    double xmin = xs.front(), xmax = xs.back();\n    vector<double> tvals; tvals.push_back(0.0);\n    for(double xv: X){ double frac = xv - floor(xv); double r1 = (fabs(frac) < 1e-12) ? 0.0 : 1.0 - frac; double r2 = fmod(0.5 - frac, 1.0); if(r2 < 0) r2 += 1.0; tvals.push_back(r1); tvals.push_back(r2); }\n    sort(tvals.begin(), tvals.end()); vector<double> ts; for(double t: tvals){ if(ts.empty() || fabs(t - ts.back()) > 1e-12) ts.push_back(t); }\n    auto At = [&](double t)->double{ double total = 0.0; int kstart = (int)floor(xmin - t) - 2; int kend = (int)floor(xmax - t) + 2; for(int k = kstart; k <= kend; ++k){ double a = k - t; double b = a + 0.5; if(b <= xmin) continue; if(a >= xmax) continue; double Fa = F_at(a); double Fb = F_at(b); total += (Fb - Fa); } return total; };\n    double best = 0.0; for(double t : ts){ double val = At(t); if(val > best) best = val; }\n    cout.setf(std::ios::fixed); cout << setprecision(9) << best << \"\\n\";\n    return 0; }\nEOF"
