#include <bits/stdc++.h>
using namespace std;

struct Pt { long long x, y; int m, p, r; int idx; };
struct Node { long long x, y; int m, p, r; int idx; int left, right; long long minx, maxx, miny, maxy; };

vector<Node> tree;

int build(int l, int r, int depth, vector<Pt>& a){
    if(l > r) return -1;
    int axis = depth & 1; // 0 -> x, 1 -> y
    int mid = (l + r) >> 1;
    auto cmp = [axis](const Pt& A, const Pt& B){
        if(axis==0){ if(A.x != B.x) return A.x < B.x; if(A.y != B.y) return A.y < B.y; return A.idx < B.idx; }
        else{ if(A.y != B.y) return A.y < B.y; if(A.x != B.x) return A.x < B.x; return A.idx < B.idx; }
    };
    nth_element(a.begin()+l, a.begin()+mid, a.begin()+r+1, cmp);
    int left = build(l, mid-1, depth+1, a);
    int right = build(mid+1, r, depth+1, a);
    Node nd;
    nd.x = a[mid].x; nd.y = a[mid].y; nd.m = a[mid].m; nd.p = a[mid].p; nd.r = a[mid].r; nd.idx = a[mid].idx;
    nd.left = left; nd.right = right;
    nd.minx = nd.maxx = nd.x; nd.miny = nd.maxy = nd.y;
    if(left != -1){ nd.minx = min(nd.minx, tree[left].minx); nd.maxx = max(nd.maxx, tree[left].maxx); nd.miny = min(nd.miny, tree[left].miny); nd.maxy = max(nd.
maxy, tree[left].maxy); }
    if(right != -1){ nd.minx = min(nd.minx, tree[right].minx); nd.maxx = max(nd.maxx, tree[right].maxx); nd.miny = min(nd.miny, tree[right].miny); nd.maxy = max
(nd.maxy, tree[right].maxy); }
    int cur = (int)tree.size();
    tree.push_back(nd);
    return cur;
}

void query(int u, long long cx, long long cy, int p_lim, long long r2, vector<int>& found, vector<char>& visited){
    if(u==-1) return;
    const Node &nd = tree[u];
    long long dx = 0;
    if(cx < nd.minx) dx = nd.minx - cx; else if(cx > nd.maxx) dx = cx - nd.maxx;
    long long dy = 0;
    if(cy < nd.miny) dy = nd.miny - cy; else if(cy > nd.maxy) dy = cy - nd.maxy;
    long long distBox2 = dx*dx + dy*dy;
    if(distBox2 > r2) return;
    if(!visited[nd.idx] && nd.m <= p_lim){
        long long dxp = nd.x - cx;
        long long dyp = nd.y - cy;
        long long d2 = dxp*dxp + dyp*dyp;
        if(d2 <= r2){ visited[nd.idx] = 1; found.push_back(nd.idx); }
    }
    query(nd.left, cx, cy, p_lim, r2, found, visited);
    query(nd.right, cx, cy, p_lim, r2, found, visited);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x0, y0, p0, r0; int n;
    if(!(cin >> x0 >> y0 >> p0 >> r0 >> n)) return 0;

    vector<long long> gx(n), gy(n);
    vector<int> gm(n), gp(n), gr(n);
    vector<Pt> arr; arr.reserve(n);

    for(int i=0;i<n;i++){
        long long xi, yi; int mi, pi, ri;
        cin >> xi >> yi >> mi >> pi >> ri;
        gx[i] = xi; gy[i] = yi; gm[i] = mi; gp[i] = pi; gr[i] = ri;
        Pt t; t.x = xi; t.y = yi; t.m = mi; t.p = pi; t.r = ri; t.idx = i;
        arr.push_back(t);
    }

    tree.clear();
    int root = -1;
    if(n > 0) root = build(0, n-1, 0, arr);

    vector<char> visited(n, false);
    queue<int> q;
    int ans = 0;

    // Initial pull from ship position
    if(n > 0){
        vector<int> found;
        long long r2 = r0 * r0;
        query(root, x0, y0, (int)p0, r2, found, visited);
        for(int idx : found){ if(!visited[idx]){ visited[idx] = 1; q.push(idx); } }
    }

    // BFS over pulled grippers
    while(!q.empty()){
        int u = q.front(); q.pop();
        ++ans; // count this gripper as pulled
        long long cx = gx[u], cy = gy[u];
        int p_lim = gp[u];
        long long r2 = 1LL * gr[u] * gr[u];
        vector<int> found;
        query(root, cx, cy, p_lim, r2, found, visited);
        for(int idx : found){ if(!visited[idx]){ visited[idx] = 1; q.push(idx); } }
    }

    cout << ans << "\n";
    return 0;
}
